import java.util.ArrayList;
import java.util.List;

public class UnboundedWildcardDemo {
    // Universal inspection utility using unbounded wildcard List<?>
    public static void printCollection(List<?> list, String title) {
        System.out.println("=== " + title + " (Size: " + list.size() + ") ===");
        for (Object item : list) {
            System.out.println("  -> " + item);
        }
    }

    public static void main(String[] args) {
        List<String> names = List.of("Alice", "Bob", "Charlie");
        List<Integer> ports = List.of(80, 443, 8080);
        List<Double> latencies = List.of(12.4, 45.2, 3.1);

        // All parameterized lists are assignable to List<?>
        printCollection(names, "Service Names");
        printCollection(ports, "Open Ports");
        printCollection(latencies, "Network Latencies");

        // Writing demonstration
        List<?> wildcardHolder = new ArrayList<String>();
        // wildcardHolder.add("test"); // COMPILE ERROR: Cannot write to List<?>
        wildcardHolder.add(null); // Allowed
        System.out.println("Wildcard holds null: " + wildcardHolder.get(0));
    }
}
// Expected Output:
// === Service Names (Size: 3) ===
//   -> Alice
//   -> Bob
//   -> Charlie
// === Open Ports (Size: 3) ===
//   -> 80
//   -> 443
//   -> 8080
// === Network Latencies (Size: 3) ===
//   -> 12.4
//   -> 45.2
//   -> 3.1
// Wildcard holds null: null

