import java.util.List;
import java.util.Arrays;

public class WildcardInspector {
    public static int countNullElements(List<?> list) {
        if (list == null) return 0;
        int nullCount = 0;
        // Elements are read safely as java.lang.Object
        for (Object elem : list) {
            if (elem == null) {
                nullCount++;
            }
        }
        return nullCount;
    }

    public static void main(String[] args) {
        List<String> strList = Arrays.asList("Alpha", null, "Beta", null, "Gamma");
        List<Integer> intList = Arrays.asList(1, 2, 3, null);

        System.out.println("String list null count:  " + countNullElements(strList)); // 2
        System.out.println("Integer list null count: " + countNullElements(intList)); // 1
    }
}

