import java.util.List;

public class CollectionReporter {
    public static String reportStatus(List<?> list) {
        if (list == null || list.isEmpty()) {
            return "Empty";
        }
        return "Size: " + list.size();
    }

    public static void main(String[] args) {
        System.out.println(reportStatus(null));
        System.out.println(reportStatus(List.of()));
        System.out.println(reportStatus(List.of(1, 2, 3)));
        System.out.println(reportStatus(List.of("a", "b")));
    }
}

