import java.util.List;

public class SizeChecker {
    public static boolean haveEqualSize(List<?> listA, List<?> listB) {
        if (listA == null || listB == null) return false;
        return listA.size() == listB.size();
    }

    public static void main(String[] args) {
        List<String> strings = List.of("x", "y");
        List<Integer> ints = List.of(10, 20);
        List<Double> doubles = List.of(1.1);
        System.out.println(haveEqualSize(strings, ints));
        System.out.println(haveEqualSize(strings, doubles));
    }
}

