practiceProblems.solutionCode:
import java.util.List;
import java.util.Arrays;

public class NullVerifier {
    public static boolean containsAnyNull(List<?> list) {
        if (list == null) return false;
        for (Object item : list) {
            if (item == null) return true;
        }
        return false;
    }

    public static void main(String[] args) {
        System.out.println(containsAnyNull(Arrays.asList("a", null, "b")));
        System.out.println(containsAnyNull(Arrays.asList(1, 2, 3)));
    }
}

