practiceProblems.solutionCode:
import java.util.List;
import java.util.Objects;
import java.util.HashSet;
import java.util.Set;

public class SharedElementAuditor {
    public static int countSharedElements(List<?> listA, List<?> listB) {
        if (listA == null || listB == null) return 0;
        Set<Object> setB = new HashSet<>(listB);
        int count = 0;
        for (Object itemA : listA) {
            if (setB.contains(itemA)) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        List<Object> a = List.of("cat", 10, "dog", 20);
        List<Object> b = List.of(10, "mouse", 20, "elephant");
        System.out.println(countSharedElements(a, b));
    }
}
